assert len(FATE_TASKS) == 200, "В базе должно быть ровно 200 заданий"
COMMAND_RE = re.compile(r"^\.судьба(?:\s+(я))?\s*$", re.I)
_unused = list(range(len(FATE_TASKS)))

def _next_task():
    global _unused
    if not _unused:
        _unused = list(range(len(FATE_TASKS)))
    index = random.choice(_unused)
    _unused.remove(index)
    return FATE_TASKS[index]

async def _random_member(client, chat_id):
    participants = []
    try:
        async for user in client.iter_participants(chat_id):
            if getattr(user, "bot", False) or getattr(user, "deleted", False):
                continue
            if user.id in (config.SELF_ID, config.OWNER_ID):
                continue
            participants.append(user)
        return random.choice(participants) if participants else None
    except Exception:
        return None

def register(client):
    @client.on(events.NewMessage(pattern=COMMAND_RE))
    async def fate_cmd(event):
        if event.is_private:
            await event.respond("🔮 `.судьба` работает в групповом чате.\n`.судьба` — случайный участник\n`.судьба я` — задание для себя.")
            return
        if not config.chat_allowed(event.chat_id):
            return
        own = bool(event.pattern_match.group(1))
        task = _next_task()
        if own:
            text = "🔮 **СУДЬБА РЕШИЛА…**\n\n{0}\n\n🍀 Удачи!".format(task)
        else:
            target = await _random_member(event.client, event.chat_id)
            if target is None:
                await event.respond("🔮 Судьба не смогла найти подходящего участника.")
                return
            text = "🔮 **СУДЬБА РЕШИЛА…**\n\n{0}\n\n🎯 Сегодня судьба выбрала {1}!".format(task, mention(target.id, target.first_name or "участника"))
        await event.respond(text)
